// Digital twin for Display.RGBW — TI LP5811 4-channel LED driver + on-tile RGBW LED.
//
// The LP5811 is a boost + 4 low-side current sinks (O0..O3). On this tile the
// RGBW LED is ON-BOARD: VOUT (boost, ~4.5 V) drives the LED common anode and the
// four sinks pull each cathode — O0=R, O1=B, O2=G, O3=W (per the tile schematic).
// So the LED channels are internal, not edge pads; the tile exposes only I²C
// (pads 4/5), EN (pad 8), V+ (pad 10), GND (pad 1). Address 0x50 (LP5811A).
//
// Two output paths, both modeled:
//   • Manual: per-channel PWM brightness (0–255) × DC current limit (0–255),
//     scaled by the max-current mode (25.5 / 51 mA full-scale).
//   • Autonomous (AEU): the on-chip animation engine runs a channel with no MCU
//     help. This twin models a single active autonomous breathe (set via
//     breathe_auto / animate_start) and evolves it over time in deriveState, so
//     the simulated LED actually breathes. Per-channel open/short + thermal faults.
//
// Brightness/current/fault/engine semantics are canonical (driver + LP5811 TRM);
// the LED forward drop + boost efficiency in the power layer are modeled.
import type { TileSim } from '../tileSim';

const I2C_ADDR = 0x50;
const VOUT_MV = 4500; // boost output to the LED common anode
const BOOST_EFF = 0.85;
const IQ_ACTIVE_UA = 1000; // LP5811 active quiescent (boost running)
const IQ_STANDBY_UA = 10; // EN low / sleep
const TICK_MS = 100; // runner deriveState cadence

// channel letters by index (O0=R, O1=B, O2=G, O3=W) — matches set_autonomous(ch)
const CH = ['r', 'b', 'g', 'w'] as const;
type Ch = (typeof CH)[number];
const FAULT_BIT: Record<Ch, number> = { r: 0, b: 1, g: 2, w: 3 };

interface State {
  // manual PWM brightness 0-255
  r: number;
  g: number;
  b: number;
  w: number;
  // per-channel DC current limit 0-255
  ir: number;
  ig: number;
  ib: number;
  iw: number;

  max_current: number; // 0 = 25.5 mA, 1 = 51 mA full-scale
  enabled: number;
  sleeping: number;

  // faults (per-channel bit: 0=R,1=B,2=G,3=W) + thermal
  open_mask: number;
  short_mask: number;
  tsd: number;
  short_shutdown: number;
  open_shutdown: number;

  // ── autonomous engine ──
  auto_r: number;
  auto_g: number;
  auto_b: number;
  auto_w: number; // per-channel autonomous-mode enable
  anim_channel: number; // which channel the active breathe drives (0-3)
  anim_peak: number; // breathe peak brightness 0-255
  anim_period_ms: number; // full breathe period
  animating: number; // engine running
  anim_paused: number;
  anim_clock: number; // ms since animate_start
  exp_mask: number; // exponential-dimming enable bits
  phase_align: number; // last-set phase-align mode (cosmetic)
  latched: number; // CMD_Update issued
  aeu_configured: number;

  vplus_mv: number;

  [field: string]: number;
}

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v));
const pick = (args: number[], i: number, cur: number) =>
  args.length > i && Number.isFinite(args[i]) ? args[i] : cur;

const maxMa = (s: State) => (s.max_current === 1 ? 51 : 25.5);
const autoOn = (s: State, ch: Ch) => s[('auto_' + ch) as keyof State] === 1;

// Triangle breathe envelope 0..1 from the animation clock (0→1→0 over period).
function animDuty(s: State): number {
  if (s.anim_period_ms <= 0) return s.anim_peak / 255; // steady hold
  const phase = (s.anim_clock % s.anim_period_ms) / s.anim_period_ms;
  return (s.anim_peak / 255) * (1 - Math.abs(2 * phase - 1));
}

// A channel's PWM duty 0..1: the autonomous breathe when this channel is the
// active animated one, otherwise its manual brightness register.
function duty(s: State, ch: Ch): number {
  if (autoOn(s, ch) && s.animating === 1 && s.anim_channel === FAULT_BIT[ch]) {
    return s.anim_paused === 1 ? animDuty({ ...s }) : animDuty(s);
  }
  return (s[ch] as number) / 255;
}

// Channel output level 0..1 = duty × current fraction, zeroed when off/asleep or
// the channel has a disabling fault (open, or short with shutdown enabled).
function level(s: State, ch: Ch): number {
  if (s.enabled !== 1 || s.sleeping === 1) return 0;
  const bit = 1 << FAULT_BIT[ch];
  if (s.open_mask & bit) return 0;
  if (s.short_mask & bit && s.short_shutdown === 1) return 0;
  const ilim = s[('i' + ch) as keyof State] as number;
  return clamp(duty(s, ch) * (ilim / 255), 0, 1);
}

const chMa = (s: State, ch: Ch) => level(s, ch) * maxMa(s);

// ms → AEU slope/pause code (driver's lp_time_ms table), nearest match.
const SLOPE_MS = [
  0, 90, 180, 360, 540, 800, 1070, 1520, 2060, 2500, 3040, 4020, 5010, 5990, 7060, 8050,
];
function msToSlope(ms: number): number {
  let best = 0;
  let bestErr = Infinity;
  for (let i = 0; i < 16; i++) {
    const err = Math.abs(ms - SLOPE_MS[i]);
    if (err < bestErr) {
      bestErr = err;
      best = i;
    }
  }
  return best;
}

const sim: TileSim<State> = {
  tile: 'Display.RGBW',

  defaultState: {
    r: 0,
    g: 0,
    b: 0,
    w: 0,
    ir: 128,
    ig: 128,
    ib: 128,
    iw: 128,
    max_current: 1,
    enabled: 1,
    sleeping: 0,
    open_mask: 0,
    short_mask: 0,
    tsd: 0,
    short_shutdown: 0,
    open_shutdown: 1,
    auto_r: 0,
    auto_g: 0,
    auto_b: 0,
    auto_w: 0,
    anim_channel: 0,
    anim_peak: 255,
    anim_period_ms: 2000,
    animating: 0,
    anim_paused: 0,
    anim_clock: 0,
    exp_mask: 0,
    phase_align: 0,
    latched: 0,
    aeu_configured: 0,
    vplus_mv: 3700,
  },

  controls: [
    { type: 'slider', field: 'r', label: 'Red', min: 0, max: 255, step: 1 },
    { type: 'slider', field: 'g', label: 'Green', min: 0, max: 255, step: 1 },
    { type: 'slider', field: 'b', label: 'Blue', min: 0, max: 255, step: 1 },
    { type: 'slider', field: 'w', label: 'White', min: 0, max: 255, step: 1 },
    { type: 'toggle', field: 'animating', label: 'Autonomous run' },
    { type: 'slider', field: 'anim_channel', label: 'Anim ch (0R1B2G3W)', min: 0, max: 3, step: 1 },
    {
      type: 'slider',
      field: 'anim_period_ms',
      label: 'Breathe period',
      min: 200,
      max: 8000,
      step: 100,
      unit: 'ms',
    },
    { type: 'toggle', field: 'enabled', label: 'Enabled' },
  ],

  // Evolve the autonomous breathe: advance the engine clock while running.
  deriveState(state) {
    if (state.animating !== 1 || state.anim_paused === 1) return {};
    // Auto-enable the active channel so the envelope shows even if the user
    // toggled `animating` directly rather than via breathe_auto.
    const chKey = 'auto_' + CH[clamp(Math.round(state.anim_channel), 0, 3)];
    return { anim_clock: state.anim_clock + TICK_MS, [chKey]: 1 };
  },

  hostCalls: {
    // ── lifecycle ──
    tile_display_rgbw_find: () => ({ scalar: I2C_ADDR }),
    tile_display_rgbw_init: () => ({
      scalar: 0,
      nextState: { enabled: 1, max_current: 1, r: 0, g: 0, b: 0, w: 0, animating: 0 },
    }),
    tile_display_rgbw_sleep: () => ({ nextState: { sleeping: 1 } }),
    tile_display_rgbw_wake: () => ({ nextState: { sleeping: 0 } }),
    tile_display_rgbw_reset: () => ({
      nextState: {
        r: 0,
        g: 0,
        b: 0,
        w: 0,
        open_mask: 0,
        short_mask: 0,
        tsd: 0,
        enabled: 1,
        animating: 0,
      },
    }),

    // ── manual output ──
    tile_display_rgbw_set: ({ args }) => ({
      nextState: {
        r: clamp(pick(args, 0, 0), 0, 255),
        g: clamp(pick(args, 1, 0), 0, 255),
        b: clamp(pick(args, 2, 0), 0, 255),
        w: clamp(pick(args, 3, 0), 0, 255),
      },
    }),
    tile_display_rgbw_set_color: ({ args }) => ({
      nextState: {
        r: clamp(pick(args, 0, 0), 0, 255),
        g: clamp(pick(args, 1, 0), 0, 255),
        b: clamp(pick(args, 2, 0), 0, 255),
      },
    }),
    tile_display_rgbw_off: () => ({ nextState: { r: 0, g: 0, b: 0, w: 0, animating: 0 } }),
    tile_display_rgbw_set_current: ({ args }) => ({
      nextState: {
        ir: clamp(pick(args, 0, 128), 0, 255),
        ig: clamp(pick(args, 1, 128), 0, 255),
        ib: clamp(pick(args, 2, 128), 0, 255),
        iw: clamp(pick(args, 3, 128), 0, 255),
      },
    }),
    tile_display_rgbw_set_max_current: ({ args }) => ({
      nextState: { max_current: pick(args, 0, 1) ? 1 : 0 },
    }),

    // ── host-side animation helpers (steady target modeled, timing not simulated) ──
    tile_display_rgbw_pulse: ({ args }) => ({
      nextState: {
        r: clamp(pick(args, 0, 0), 0, 255),
        g: clamp(pick(args, 1, 0), 0, 255),
        b: clamp(pick(args, 2, 0), 0, 255),
      },
    }),
    tile_display_rgbw_breathe: ({ args }) => ({
      nextState: {
        r: clamp(pick(args, 0, 0), 0, 255),
        g: clamp(pick(args, 1, 0), 0, 255),
        b: clamp(pick(args, 2, 0), 0, 255),
      },
    }),
    tile_display_rgbw_flash: ({ args }) => ({
      nextState: {
        r: clamp(pick(args, 0, 0), 0, 255),
        g: clamp(pick(args, 1, 0), 0, 255),
        b: clamp(pick(args, 2, 0), 0, 255),
      },
    }),

    // ── faults ──
    tile_display_rgbw_read_faults: ({ state }) => ({
      scalar:
        (state.tsd ? 1 << 8 : 0) | ((state.short_mask & 0x0f) << 4) | (state.open_mask & 0x0f),
    }),
    tile_display_rgbw_clear_faults: () => ({ nextState: { open_mask: 0, short_mask: 0, tsd: 0 } }),
    tile_display_rgbw_is_faulted: ({ state }) => ({
      scalar: state.open_mask || state.short_mask || state.tsd ? 1 : 0,
    }),
    tile_display_rgbw_set_short_threshold: () => ({ nextState: {} }),
    tile_display_rgbw_set_short_shutdown: ({ args }) => ({
      nextState: { short_shutdown: pick(args, 0, 0) ? 1 : 0 },
    }),
    tile_display_rgbw_set_open_shutdown: ({ args }) => ({
      nextState: { open_shutdown: pick(args, 0, 1) ? 1 : 0 },
    }),

    // ── autonomous animation engine (AEU) ──
    tile_display_rgbw_ms_to_slope: ({ args }) => ({ scalar: msToSlope(pick(args, 0, 0)) }),
    tile_display_rgbw_set_autonomous: ({ args }) => {
      const ch = clamp(pick(args, 0, 0), 0, 3);
      const on = pick(args, 1, 1) ? 1 : 0;
      return { nextState: { ['auto_' + CH[ch]]: on } };
    },
    tile_display_rgbw_set_aeu: ({ args }) => ({
      // Struct arg can't pass through flat args; capture the channel + (best-effort)
      // a peak/period so the engine demo has something to play.
      nextState: { aeu_configured: 1, anim_channel: clamp(pick(args, 0, 0), 0, 3) },
    }),
    tile_display_rgbw_set_animation: ({ args }) => ({
      nextState: { anim_channel: clamp(pick(args, 0, 0), 0, 3) },
    }),
    tile_display_rgbw_set_exp_dimming: ({ state, args }) => {
      const bit = 1 << clamp(pick(args, 0, 0), 0, 3);
      const on = pick(args, 1, 1) ? 1 : 0;
      return { nextState: { exp_mask: on ? state.exp_mask | bit : state.exp_mask & ~bit } };
    },
    tile_display_rgbw_set_phase_align: ({ args }) => ({
      nextState: { phase_align: clamp(pick(args, 1, 0), 0, 3) },
    }),
    tile_display_rgbw_update: () => ({ nextState: { latched: 1 } }),
    tile_display_rgbw_animate_start: () => ({
      nextState: { animating: 1, anim_paused: 0, anim_clock: 0 },
    }),
    tile_display_rgbw_animate_stop: () => ({
      nextState: { animating: 0, anim_paused: 0, anim_clock: 0 },
    }),
    tile_display_rgbw_animate_pause: () => ({ nextState: { anim_paused: 1 } }),
    tile_display_rgbw_animate_continue: () => ({ nextState: { anim_paused: 0 } }),
    tile_display_rgbw_breathe_auto: ({ args }) => {
      const ch = clamp(pick(args, 0, 0), 0, 3);
      return {
        nextState: {
          anim_channel: ch,
          ['auto_' + CH[ch]]: 1,
          anim_peak: clamp(pick(args, 1, 255), 0, 255),
          anim_period_ms: pick(args, 2, 2000),
          animating: 1,
          anim_paused: 0,
          anim_clock: 0,
          exp_mask: 1 << ch,
        },
      };
    },
  },

  provenance: {
    tile_display_rgbw_find: 'canonical',
    tile_display_rgbw_set: 'canonical',
    tile_display_rgbw_set_current: 'canonical',
    tile_display_rgbw_set_max_current: 'canonical',
    tile_display_rgbw_read_faults: 'canonical',
    tile_display_rgbw_clear_faults: 'canonical',
    tile_display_rgbw_off: 'canonical',
    // autonomous engine — register-accurate command/config semantics
    tile_display_rgbw_set_autonomous: 'canonical', // Dev_Config_3 auto_en
    tile_display_rgbw_ms_to_slope: 'canonical', // lp_time_ms table
    tile_display_rgbw_animate_start: 'canonical', // CMD 0xFF
    tile_display_rgbw_animate_stop: 'canonical', // CMD 0xAA
    tile_display_rgbw_animate_pause: 'canonical', // CMD 0x33
    tile_display_rgbw_animate_continue: 'canonical', // CMD 0xCC
    tile_display_rgbw_update: 'canonical', // CMD 0x55 latch
    tile_display_rgbw_set_exp_dimming: 'canonical', // Dev_Config_5
    tile_display_rgbw_set_phase_align: 'canonical', // Dev_Config_7
    // inferred / partially modeled
    tile_display_rgbw_set_color: 'inferred',
    tile_display_rgbw_init: 'inferred',
    tile_display_rgbw_sleep: 'inferred',
    tile_display_rgbw_wake: 'inferred',
    tile_display_rgbw_reset: 'inferred',
    tile_display_rgbw_is_faulted: 'inferred',
    tile_display_rgbw_set_short_shutdown: 'inferred',
    tile_display_rgbw_set_open_shutdown: 'inferred',
    tile_display_rgbw_set_animation: 'inferred', // chains AEUs; only channel captured
    tile_display_rgbw_breathe_auto: 'inferred', // builds a breathe AEU program
    // hallucinated — can't model from flat args / not simulated
    tile_display_rgbw_set_aeu: 'hallucinated', // 5-keyframe struct arg can't pass through
    tile_display_rgbw_pulse: 'hallucinated',
    tile_display_rgbw_breathe: 'hallucinated',
    tile_display_rgbw_flash: 'hallucinated',
    tile_display_rgbw_set_short_threshold: 'hallucinated',
    power: 'inferred',
  },

  // The on-tile RGBW LED — per-channel intensity 0..1 (manual or live breathe).
  padOutputs(state) {
    return {
      R: level(state, 'r'),
      G: level(state, 'g'),
      B: level(state, 'b'),
      W: level(state, 'w'),
    };
  },

  power(state) {
    if (state.enabled !== 1 || state.sleeping === 1) {
      return {
        draw_ua: IQ_STANDBY_UA,
        rails: [
          {
            name: 'V+',
            role: 'supply',
            v_mv: state.vplus_mv,
            i_ua: IQ_STANDBY_UA,
            pads: ['10'],
            note: 'standby',
          },
        ],
      };
    }
    const ledMa = chMa(state, 'r') + chMa(state, 'g') + chMa(state, 'b') + chMa(state, 'w');
    const inUa = (ledMa * 1000 * VOUT_MV) / (BOOST_EFF * state.vplus_mv);
    const drawUa = Math.round(IQ_ACTIVE_UA + inUa);
    return {
      draw_ua: drawUa,
      rails: [
        {
          name: 'V+',
          role: 'supply',
          v_mv: state.vplus_mv,
          i_ua: drawUa,
          pads: ['10'],
          note: 'boost input + LED current',
        },
        {
          name: 'VLED',
          role: 'output',
          v_mv: ledMa > 0 ? VOUT_MV : 0,
          note: 'boosted LED common-anode (on-tile)',
        },
      ],
    };
  },
};

export default sim;
